#!/bin/zsh
# Q 版素材生圖：tools/art_gen.sh <id> <sheet...>
#   sheet：同事 idle（3 方向待機 12 格）、idle_diag（斜前／斜後待機 8 格）、atk_down|dside|side|uside|up；敵人 walk_down|side|up（8 格）、extra（站姿＋受擊三方向＋特殊姿勢）
#   例：tools/art_gen.sh yan atk_down atk_side atk_up   （最多三張同時跑）
# 參考圖：idle 用 design/art/ref/<id>_ref.png（畫風條＋RPG 原圖）；atk 用已生好的 design/art/raw/<id>_idle.png，畫風與造型才一致
cd ${0:A:h}/..
. tools/art_prompts.sh
G=/Users/hermes/Public/0720/a4-rpg-battle/tools/gen.sh
id=$1; shift
typeset -A DESC ACT
DESC[kui]="Character: the girl from the reference — short brown bob hair, orange-brown beret, round glasses, red scarf, silver steel breastplate with shoulder pads over a cream knit sweater, brown strap and small brown satchel at the hip, dark navy floral skirt, brown leather gloves, brown boots, ONE straight steel sword."
ACT[kui]="Attack: a swordswoman's quick slash. 1 ready stance sword up, 2 crouch and pull the sword back, 3 step forward winding up, 4 begin the swing, 5 full slash with a short white crescent slash trail, 6 follow-through with the trail fading, 7 recover upright, 8 ready stance."
DESC[jie]="Character: the wizard from the reference — long curly brown hair, brown beard, round glasses, wide purple witch hat with a magenta band, dark purple robe with gold trim, olive-brown cape with a gold round clasp, brown belt with gold buckle, brown boots, a twisted wooden staff with a forked top in his right hand."
ACT[jie]="Attack: a dark mage casting a purple-black flame. 1 ready stance holding the staff upright, 2 raise the staff, a small purple glow at the staff tip, 3 staff high above the head gathering a purple flame orb, 4 swing the staff forward, 5 staff pointed forward and a purple-black fireball bursts from the tip, 6 the fireball leaves and the cape flutters, 7 lower the staff, 8 ready stance."
DESC[kevin]="Character: the knight from the reference — spiky black hair with cyan tips, white wireless earbud, black turtleneck, dark gunmetal full plate armor with layered shoulder pads, gauntlets and greaves, a tall dark rectangular tower shield with glowing cyan edge lines, always held in his LEFT hand (in front view it is on the right side of the image; in back and three-quarter back views it is on the LEFT side of the image). No other weapon."
ACT[kevin]="Attack: a tank's shield bash. 1 ready stance with the tower shield planted in front, 2 pull the shield close and crouch, 3 lower the shoulder behind the shield, 4 lunge forward, 5 slam the shield forward with a short cyan impact flash on the shield face, 6 slight recoil, 7 bring the shield back, 8 ready stance."
DESC[yan]="Character: the woman from the reference — long wavy reddish-brown hair in a high ponytail, navy blue suit jacket and navy trousers, short navy cape with gold trim and a gold chain, white shirt, blue lanyard with a white ID badge, black low heels, a golden staff topped with an hourglass."
ACT[yan]="Attack: an ice and time mage. 1 ready stance holding the hourglass staff, 2 lift the staff, pale blue snowflake sparkles gather, 3 staff raised overhead and the hourglass glows icy blue, 4 swing the staff forward, 5 staff thrust forward and a burst of icy blue crystals shoots out, 6 crystals scatter and fade, 7 lower the staff, 8 ready stance."
DESC[zhe]="Character: the young man from the reference — messy spiky brown hair with an ahoge, a band-aid on his cheek, white rolled-sleeve office shirt, red necktie, red armband, white ID badge, brown leather shoulder pad and strap, khaki trousers, white sneakers, a long wooden spear tipped with a red-and-white rocket-shaped lance head."
ACT[zhe]="Attack: a lancer's fiery thrust. 1 ready stance holding the rocket lance upright, 2 bring the lance level at the hip, 3 crouch low and draw the lance back, 4 lunge forward, 5 full thrust with the lance tip forward and a short orange flame burst at the tip, 6 hold the thrust as the flame fades, 7 pull the lance back, 8 ready stance."
DESC[mi]="Character: the girl from the reference — straight dark brown bob with bangs, black headset with a microphone, white hooded cleric robe with gold cross patterns, navy sailor collar with a navy striped bow, navy skirt under the robe, black shoes, a golden ornate scepter staff."
ACT[mi]="Attack: a healer's blessing. 1 ready stance holding the golden scepter with both hands at the chest, 2 close her eyes, small golden light dots gather, 3 raise the scepter high, the top glows gold, 4 swing the scepter forward, 5 scepter pointed forward releasing a soft golden ring of light with tiny sparkles, 6 the sparkles drift and fade, 7 lower the scepter, 8 ready stance."
DESC[heilun]="Character: the salesman from the reference — messy spiky dark grey hair, stubble, smug smile, worn dark grey suit jacket with patches, white shirt, striped navy tie, brown leather bandolier holding rolled contract scrolls with red wax seals, navy trousers, black shoes, a brown leather briefcase in his left hand."
ACT[heilun]="Attack: a salesman flinging a business card. 1 ready stance holding the briefcase, 2 pull a white business card from his chest pocket, 3 wind up the throwing arm far back, 4 step forward, 5 fling the card: it flies forward with a short white streak, 6 throwing arm extended, 7 straighten up, 8 ready stance."
DESC[cha]="Character: the woman from the reference — straight brown bob with bangs, mint-green capelet tied with a green bow, cream puff-sleeve blouse, beige pencil skirt, beige heels, a bubble-tea cup with a straw in her left hand and a slim wooden stirring wand in her right hand."
ACT[cha]="Attack: a support who sends bubble tea power. 1 ready stance holding the bubble tea, 2 raise the wand happily, 3 wand high, small golden bubbles appear, 4 swing the wand forward, 5 wand pointed forward releasing a stream of round golden tapioca-bubble sparkles, 6 sparkles drift and fade, 7 lower the wand, 8 ready stance."
DESC[qiang]="Character: the brawler from the reference — black baseball cap, short black hair, stubble, rolled-up white shirt, navy tie, a large wooden prayer-bead necklace, white bandages wrapped around both fists and forearms, brown rope belt, dark navy trousers, black shoes."
ACT[qiang]="Attack: a heavy straight punch. 1 fighting stance fists up, 2 crouch and pull the right fist back, 3 twist the body winding up, 4 step in, 5 full straight punch with the fist forward and a short white-yellow impact burst at the fist, 6 hold the punch as the burst fades, 7 pull the fist back, 8 fighting stance."
DESC[senpai]="Character: the detective woman from the reference — messy shoulder-length dark brown hair with reddish highlights, sharp eyes, beige jacket, white collared shirt, brown leather strap and satchel, khaki shorts, black loafers, carrying a giant brass magnifying glass with a long wooden handle."
ACT[senpai]="Attack: a detective sniping with a giant magnifying glass. 1 ready stance with the magnifying glass on her shoulder, 2 bring it down with both hands, 3 aim it forward and squint, 4 the lens glows, 5 a thin bright focused light beam shoots straight out of the lens, 6 the beam fades, 7 lift it back up, 8 ready stance."
DESC[wu]="Character: the dancer girl from the reference — wavy reddish-brown side ponytail with a big pink gingham bow, puffy pink sleeves, colorful patchwork dress (pink gingham, blue polka dots, yellow panels), pearl necklace, pink ribbons on her wrists, red shoes, a folding fan in each hand."
ACT[wu]="Attack: a spinning fan dance. 1 ready pose with both fans, 2 open the fans and step, 3 begin to spin with ribbons trailing, 4 mid-spin, 5 fans swept wide with a pink crescent wind trail around her, 6 ribbons settle, 7 finishing pose, 8 ready pose."
DESC[you]="Character: the sly veteran from the reference — slicked-back dark undercut hair, round gold glasses, mustache and goatee, dark navy suit with a dark brown cape, light blue shirt, gold chain, a belt with a ring of keys, a canned drink in his left hand and a small silver knife in his right hand."
ACT[you]="Attack: a quick thief stab. 1 relaxed ready stance, 2 lean forward and lower the knife, 3 crouch low with the cape flaring, 4 dash forward, 5 lunge with the knife thrust forward and a thin white glint at the tip, 6 hold the lunge, 7 straighten up, 8 relaxed ready stance."
DESC[fairy]="Character: the fairy girl from the reference — brown hair in a high ponytail with a big white lace bow and pearls, off-shoulder white ruffled lace dress, red pearl necklace, translucent lilac fairy wings, white heels, a slim wand with a small star tip."
ACT[fairy]="Attack: a fairy summoner. 1 ready pose holding the wand, 2 wings flutter and she raises the wand, 3 wand high with a twinkling star, 4 swing the wand forward, 5 wand pointed forward releasing a puff of white sparkles and tiny stars, 6 sparkles fade, 7 lower the wand, 8 ready pose."
DESC[xu]="Character: the pharmacist girl from the reference — dark red hair in a bun with a grey bow and side locks, dark grey vest over a white puff-sleeve shirt, red striped bow tie, grey pleated skirt, brown satchel with small potion bottles, black shoes, a round green potion flask in her right hand."
ACT[xu]="Attack: throwing an icy potion. 1 ready stance holding the green flask, 2 shake the flask, 3 wind up the throwing arm, 4 step forward, 5 toss the flask forward: it flies with a small icy blue mist trail, 6 throwing arm extended, 7 take a new flask from the satchel, 8 ready stance."
DESC[an]="Character: the safety guard girl from the reference — yellow hard hat, long dark purple braid, orange high-visibility safety vest with reflective stripes, white shirt, grey shoulder pads and knee pads, navy cargo pants, black boots, grey work gloves, a yellow wet-floor caution sign held as a shield in her right hand, a red fire extinguisher in her left hand."
ACT[an]="Attack: a shield bash with the caution sign. 1 ready stance with the sign planted, 2 lift the sign, 3 crouch behind it, 4 charge forward, 5 slam the sign forward with a short icy blue impact flash, 6 slight recoil, 7 set the sign down, 8 ready stance."
DESC[vivi]="Character: the princess boss from the reference — very long golden blonde hair, small pink-gold tiara with a gem, long crimson-pink princess gown with gold embroidery, white gloves, a short pink jeweled scepter. Proud tsundere queen expression (chin slightly up, faint smirk, no blush)."
ACT[vivi]="Attack: a princess commanding. 1 proud ready stance, 2 lift the scepter, 3 scepter high glowing gold, 4 swing it forward, 5 scepter pointed forward releasing a golden star sparkle, the gown swirling, 6 sparkle fades, 7 lower the scepter, 8 proud ready stance."
DESC[foe_minion]="Character: the overworked office zombie from the reference — messy black hair, red headband, dark eye bags, tired face, torn dark purple suit with loose shirt and tie, a brown briefcase, carrying a giant black fountain pen like a spear."
DESC[foe_courier]="Character: the deadline courier from the reference — brown flat cap with a white feather, messy dark hair, panicked face, a big brass alarm clock strapped on his back, brown messenger bag, rolled-up sleeves, red scarf, brown trousers, red sneakers, a rolled document in his hand."
DESC[foe_knight]="Character: the filing-cabinet heavy soldier from the reference — stocky, wears a grey metal filing-cabinet drawer as a helmet, armor made of grey filing-cabinet parts with brass drawer handles, green tie, tired eyes, a whole grey filing cabinet as a big shield, a wooden mallet over his shoulder."
DESC[foe_intern]="Character: the energy-drink intern from the reference — messy brown hair, young tired face, torn navy suit, white ID badge, a wooden crate backpack full of green energy-drink bottles, more bottles at the hip, drinking from a green bottle."
DESC[foe_auntie]="Character: the gossip auntie coworker from the reference — curly lavender-grey permed hair, glasses, green floral cardigan, long maroon skirt, an open brown gossip notebook in one hand, a feather duster in the other, a red thermos at the hip."
DESC[foe_chief]="Character: the blame-shifting section chief boss from the reference — balding middle-aged man with a thin combover, glasses, sly toothy grin, white shirt, dark brown vest, red tie, a stained apron, a huge black wok strapped on his back, a big metal spatula over his shoulder, brown shoes. Large and imposing but still chibi."
DESC[foe_boss]="Character: the tyrant customer CEO final boss from the reference — huge fat man, slicked-back grey hair, smug grin, crimson suit with gold embroidery and gold buttons, gold tie, gold chains, black fur-collared cape with gold fringe, gold rings, a giant red gavel hammer over his shoulder, a long complaint scroll in the other hand. Large and imposing but still chibi."
WALK8="Layout: exactly 2 rows x 4 columns = 8 full-body figures of the same character, same scale, evenly spaced on a plain flat light gray background (#DDDDDD), no grid lines, no text, no ground shadows, figures never touch. Read left to right, top row then bottom row = frames 1 to 8 of ONE looping walk cycle (1 contact right foot forward, 2 down, 3 passing, 4 up, 5 contact left foot forward, 6 down, 7 passing, 8 up). Feet on the same baseline in each row. Exactly two arms and two legs, simple compact mitten-like pixel hands."
EXTRA="Layout: exactly ONE row of full-body figures of the same character, same scale, same camera (seen from slightly above), evenly spaced left to right on a plain flat light gray background (#DDDDDD), no grid lines, no text, no ground shadows, figures never touch. Figure 1: plain standing pose, front view facing the viewer. Figure 2: hit reaction, front view: flinching backward, eyes squeezed shut, a small white impact star near the chest (cartoon, no blood). Figure 3: the same hit reaction in strict side view facing RIGHT. Figure 4: the same hit reaction in back view (face not visible). Exactly two arms and two legs per figure, simple compact mitten-like pixel hands."
typeset -A POSE
POSE[foe_intern]="collapsed on the floor, lying face down exhausted with the bottle crate spilled beside him, eyes as swirls (knocked out but cute, not gory)."
POSE[foe_chief]="holding the huge black wok up in front of himself with both hands like a shield, guarding, smug."
POSE[foe_boss]="unrolling the long complaint scroll with both hands so it hangs down to the floor, charging up an angry rant, gavel tucked under his arm."
WFRONT="All 8 frames: walking toward the viewer / toward the bottom of the screen, front view seen from slightly above (top-down 3/4 RPG camera)."
WSIDE="All 8 frames: strict side view walking to the RIGHT (body, head and eyes all point right, profile, never looking at the viewer)."
WBACK="All 8 frames: back view walking away from the viewer toward the top of the screen (face not visible)."
need() { for i in {1..120}; do [ -s "$1" ] && return 0; sleep 5; done; echo "no ref $1"; return 1; }   # 參考圖還在生就等
for sh in $@; do
  if [[ $sh == atk_* || $sh == idle_diag ]]; then need design/art/raw/${id}_idle.png || continue; fi
  if [[ $sh == atk_dside || $sh == atk_uside ]]; then need design/art/raw/${id}_idle_diag.png || continue; fi
  if [[ $sh == walk_side || $sh == walk_up || $sh == extra ]]; then need design/art/raw/${id}_walk_down.png || continue; fi
  case $sh in
    idle)     $G design/art/raw/${id}_idle.png "$STYLE ${DESC[$id]} $(cat design/art/raw/idle_layout.txt)" design/art/ref/${id}_ref.png & ;;
    atk_down) $G design/art/raw/${id}_atk_down.png "$STYLE ${DESC[$id]} $LAYOUT8 $FRONT ${ACT[$id]} Simple compact mitten-like pixel hands." design/art/raw/${id}_idle.png & ;;
    atk_side) $G design/art/raw/${id}_atk_side.png "$STYLE ${DESC[$id]} $LAYOUT8 $SIDE ${ACT[$id]} Simple compact mitten-like pixel hands." design/art/raw/${id}_idle.png & ;;
    atk_up)   $G design/art/raw/${id}_atk_up.png "$STYLE ${DESC[$id]} $LAYOUT8 $BACK ${ACT[$id]} The weapon and effect stay visible beside the shoulder or above the head. Simple compact mitten-like pixel hands." design/art/raw/${id}_idle.png & ;;
    idle_diag) $G design/art/raw/${id}_idle_diag.png "$STYLE ${DESC[$id]} $(cat design/art/raw/diag_layout.txt)" design/art/raw/${id}_idle.png & ;;
    atk_dside) $G design/art/raw/${id}_atk_dside.png "$STYLE ${DESC[$id]} $LAYOUT8 $DSIDE ${ACT[$id]} Simple compact mitten-like pixel hands." design/art/raw/${id}_idle_diag.png & ;;
    atk_uside) $G design/art/raw/${id}_atk_uside.png "$STYLE ${DESC[$id]} $LAYOUT8 $USIDE ${ACT[$id]} The weapon and effect stay visible beside the shoulder or above the head. Simple compact mitten-like pixel hands." design/art/raw/${id}_idle_diag.png & ;;
    walk_down) $G design/art/raw/${id}_walk_down.png "$STYLE ${DESC[$id]} $WALK8 $WFRONT" design/art/ref/${id}_ref.png & ;;
    walk_side) $G design/art/raw/${id}_walk_side.png "$STYLE ${DESC[$id]} $WALK8 $WSIDE" design/art/raw/${id}_walk_down.png & ;;
    walk_up)   $G design/art/raw/${id}_walk_up.png "$STYLE ${DESC[$id]} $WALK8 $WBACK" design/art/raw/${id}_walk_down.png & ;;
    extra)     $G design/art/raw/${id}_extra.png "$STYLE ${DESC[$id]} $EXTRA ${POSE[$id]:+Figure 5 (front view): ${POSE[$id]}} ${POSE[$id]:-There are exactly 4 figures.}" design/art/raw/${id}_walk_down.png & ;;
  esac
done
wait
